// Generated by go-anything: one call in, one answer out, for the stdio bridge.
package port

import (
	"fmt"
	"math"
)

// Answer runs one call and never lets a panic out: the host sees a reply, not a dead process.
func Answer(name string, args []any) map[string]any {
	fn, ok := Registry[name]
	if !ok {
		return map[string]any{"error": "not ported: " + name}
	}
	defer func() {
		_ = recover()
	}()
	v, err := safeCall(fn, DecodeArgs(args))
	if err != nil {
		return map[string]any{"error": err.Error()}
	}
	return map[string]any{"ok": mark(v)}
}

// mark writes NaN, ±Infinity, -0 and code units the way the original's codec does, so a host sees
// values rather than spellings JSON cannot carry.
func mark(v any) any {
	switch x := v.(type) {
	case float64:
		switch {
		case math.IsNaN(x):
			return map[string]any{"$number": "NaN"}
		case math.IsInf(x, 1):
			return map[string]any{"$number": "Infinity"}
		case math.IsInf(x, -1):
			return map[string]any{"$number": "-Infinity"}
		case x == 0 && math.Signbit(x):
			return map[string]any{"$number": "-0"}
		}
		return x
	case []uint16:
		out := make([]any, len(x))
		for i, u := range x {
			out[i] = float64(u)
		}
		return map[string]any{"$utf16": out}
	case []any:
		out := make([]any, len(x))
		for i, item := range x {
			out[i] = mark(item)
		}
		return out
	case map[string]any:
		out := make(map[string]any, len(x))
		for k, item := range x {
			out[k] = mark(item)
		}
		return out
	}
	return v
}

// safeCall turns a panic into an error a host can raise.
func safeCall(fn Fn, args []any) (v any, err error) {
	defer func() {
		if r := recover(); r != nil {
			v, err = nil, fmt.Errorf("panic: %v", r)
		}
	}()
	return fn(args)
}
